# ============================================================================
# Dead Arrival map: HOLLOW LINE
# A great war trench network with two deep bunkers. You can never leave
# the line: there are no stairs up, the parapets are too tall to climb.
# spawn_mode = drop  -> zombies drop in from the parapets above
#
# Layout (north to south, trench floor tops at -2.65, berm tops at 0):
#   outer parapet -> reserve trench -> berm w/ comm links -> main trench
#   -> berm w/ comm links -> reserve trench -> outer parapet
# Two bunkers are dug into the berm at the east/west ends of the main trench.
# ============================================================================
name = Hollow Line
desc = They come from above
author = Faded Dream
spawn_mode = drop
ambient = 150 142 128
sky = 24 25 27
player_spawn = -15 -2.65 0 180

# ---- trench + bunker floor slab (bottom -3.15, top at -2.65) ----
box = 0 -3.15 0 34 0.5 24 floor_mud

# ---- berm fill: sits on the floor (bottom -2.65), tops at 0 ----
# outer parapets beyond the reserve trenches
